  public static func add(TAIL_LIMIT: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TAIL_LIMIT, def: 0.01, at: VT.TAIL_LIMIT) }
  public static func add(MINIMUM_SAMPLES: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MINIMUM_SAMPLES, def: 30, at: VT.MINIMUM_SAMPLES) }
  public static func add(MINIMUM_OBJECTS: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MINIMUM_OBJECTS, def: 3, at: VT.MINIMUM_OBJECTS) }
  public static func add(RULE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RULE, at: VT.RULE) }
  public static func addVectorOf(NOMINAL: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: NOMINAL, at: VT.NOMINAL) }
