    try _v.visit(field: VT.MINIMUM_OBJECTS, fieldName: "MINIMUM_OBJECTS", required: false, type: UInt32.self)
    try _v.visit(field: VT.RULE, fieldName: "RULE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.NOMINAL, fieldName: "NOMINAL", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    _v.finish()
  }
}

